"""Buyer-facing pages: one brand, three distinct ways to discover its projects."""
from build import ROOT, t, a, btn, head, nav, footer, proposal

PROJECTS = [
    ('pixel', 'Residencia 01', 'Sector de ejemplo', 'residencia-exterior-render', '/proyecto/', 'Estudios, suites y departamentos.', 'Studios, suites and apartments.'),
    ('magnus', 'Residencia 02', 'Quito', 'magnus-night-render', '/demo/#demo-medio', 'Una silueta que transforma el horizonte.', 'A silhouette that reshapes the skyline.'),
    ('sparta', 'Residencia 03', 'Sector de ejemplo', 'sparta-exterior-render', '/demo/#demo-alto', 'La arquitectura se encuentra con la ciudad.', 'Where architecture meets the city.'),
]


def photo(asset, alt, cls='', eager=False):
    image = f'<img class="{cls}" src="/assets/{asset}.png" alt="{alt}" loading="lazy" decoding="async">'
    if not eager: return image
    return image.replace(' src=', ' data-hero-src=').replace('loading="lazy"', 'loading="eager" fetchpriority="high"') + '<noscript>' + image + '</noscript>'


def demo_entry():
    return a('Probar la demo 3D','Try the 3D demo','/proyecto/?demo=3d#demo-3d','button demo-primary','data-demo3d')


def direction(key, content, cls=''):
    return f'<section class="direction-view {cls}" data-direction="{key}">{content}</section>'


def project_cards():
    return ''.join(f'''<article class="discovery-card" data-project-card="{slug}"><a href="{url}" ><figure>{photo(img, 'Render conceptual · IA de '+name)}<figcaption><span>0{i+1}</span><span>{t('Render conceptual · IA','Concept render · AI')}</span></figcaption></figure><div class="discovery-card-copy"><span class="place-label">{sector if sector=='Quito' else sector+' · Quito'}</span><h3>{name}</h3><p>{t(es,en)}</p><span class="card-link">{t('Ver demo propuesta','View proposed demo') if slug=='pixel' else t('Explorar herramientas','Explore tools')}</span><small class="project-destination-note">{t("Proyecto ficticio con recorrido completo.","Fictional project with a complete journey.") if slug=="pixel" else t("Proyecto ficticio · Herramientas de ejemplo","Fictional project · Sample tools")}</small></div></a></article>''' for i,(slug,name,sector,img,url,es,en) in enumerate(PROJECTS))


def home():
    essential = f'''<div class="essential-intro"><span class="overline">TU MARCA · PORTAFOLIO DEMO</span>{t('Encuentra tu<br>próximo <em>lugar.</em>','Find your<br>next <em>place.</em>','h1')}<p>{t('Conoce nuestros proyectos, encuentra su ubicación y conecta con el equipo de cada uno.','Explore our projects, find their location and connect with each project’s team.')}</p><div class="action-row">{a('Ver proyectos','Browse projects','#projects','button')}{a('Ver demo de Residencia 01','View Residencia 01 demo','/proyecto/','text-link')}</div><dl class="intro-facts"><div><dt>{t('CIUDAD','CITY')}</dt><dd>Quito</dd></div><div><dt>{t('EN ESTA SELECCIÓN','IN THIS SELECTION')}</dt><dd>{t('3 proyectos','3 projects')}</dd></div></dl></div><figure class="essential-image">{photo('residencia-exterior-render','Fachada de Residencia 01, Sector de ejemplo',eager=True)}<figcaption>RESIDENCIA 01 · SECTOR DE EJEMPLO</figcaption></figure>'''
    editorial = f'''<div class="editorial-masthead"><span>{t('ARQUITECTURA & VIDA URBANA','ARCHITECTURE & URBAN LIFE')}</span><span>QUITO / 01</span></div><div class="editorial-title">{t('Formas de<br><em>habitar.</em>','Ways of<br><em>living.</em>','h1')}<p>{t('Una mirada a los lugares que elegimos para vivir. Empezamos por Residencia 01, en Sector de ejemplo.','A closer look at the places we choose to call home. We begin with Residencia 01, in Sector de ejemplo.')}</p><div class="action-row">{a('Ver proyectos','Browse projects','#projects','button')}</div></div><figure class="editorial-cover">{photo('residencia-exterior-render','La fachada de Residencia 01 y sus balcones',eager=True)}<figcaption><b>01 / RESIDENCIA 01</b><span>{t('Color, ciudad y vida cotidiana.','Colour, city and everyday life.')}</span></figcaption></figure><div class="editorial-margin" aria-hidden="true">TU<br>MARCA</div>'''
    immersive = f'''<div class="immersive-scenes">{''.join(f'<div class="immersive-scene" data-scene-home="{slug}"'+('' if i==0 else ' hidden')+f'>{photo("pixel-living-render" if slug=="pixel" else img, "Visualización de "+name,eager=i==0)}</div>' for i,(slug,name,sector,img,*_) in enumerate(PROJECTS))}</div><div class="immersive-cover-copy"><span class="overline">{t('UN LUGAR PARA IMAGINARTE','A PLACE TO PICTURE YOURSELF')}</span>{t('Tu próxima<br>historia empieza<br><em>aquí.</em>','Your next<br>chapter starts<br><em>here.</em>','h1')}<p id="featured-description">{t('Entra a Residencia 01. Descubre sus espacios y explora una nueva forma de elegir tu hogar.','Step inside Residencia 01. Discover its spaces and a new way to choose your home.')}</p><div class="action-row">{a('Ver proyectos','Browse projects','#projects','button')}<a class="text-link" id="featured-link" href="/proyecto/">{t('Ver demo propuesta de Residencia 01','View proposed Residencia 01 demo')}</a></div></div><span class="immersive-image-note">{t('Renders conceptuales · IA','Concept renders · AI')}</span>'''
    out=head()+nav()+f'''<main id="main" class="discovery-home">{direction('essential',essential,'home-essential')}{direction('editorial',editorial,'home-editorial')}{direction('immersive',immersive,'home-immersive')}<section class="discovery-projects" id="projects"><div class="discovery-section-head"><span class="overline">{t('EXPLORA QUITO','EXPLORE QUITO')}</span><h2><span class="direction-copy" data-for="essential">{t('Elige por dónde empezar.','Choose where to begin.')}</span><span class="direction-copy" data-for="editorial">{t('Tres proyectos.<br>Tres miradas.','Three projects.<br>Three perspectives.')}</span><span class="direction-copy" data-for="immersive">{t('Sigue explorando.','Keep exploring.')}</span></h2><p>{t('Cada proyecto tiene su propio lugar en la ciudad. Conoce su arquitectura y encuentra al equipo que puede ayudarte.','Every project has its own place in the city. Discover its architecture and find the team who can help you.')}</p></div><div class="discovery-grid">{project_cards()}</div></section><section class="discovery-closing" id="vision"><span class="overline">TU MARCA</span>{t('La ciudad es el contexto.<br><em>Tu vida, el punto de partida.</em>','The city is the setting.<br><em>Your life is the starting point.</em>','h2')}<div><p>{t('La ubicación, los espacios y la manera de vivirlos hacen diferente a cada hogar. En Residencia 01 puedes conocer las tipologías, recorrer sus ambientes y conversar con el equipo del proyecto.','Location, spaces and the way you use them make every home different. At Residencia 01, explore the home types, discover its spaces and speak with the project team.')}</p>{a('Ver demo propuesta de Residencia 01','View proposed Residencia 01 demo','/proyecto/','button')}</div></section><section id="contact" class="buyer-contact"><span class="overline">{t('ESTA PODRÍA SER TU EXPERIENCIA','THIS COULD BE YOUR EXPERIENCE')}</span>{t('Tu próximo proyecto,<br>en una nueva dimensión.','Your next project,<br>in a new dimension.','h2')}<p>{t('Estos tres proyectos son ejemplos ficticios. Adaptamos el diseño, los datos y el recorrido a tu marca y a tu inventario.','These three projects are fictional examples. We adapt the design, data and journey to your brand and inventory.')}</p>{a('Conversar con Andean Software Lab','Talk to Andean Software Lab','/contacto/','button')}</section></main>'''+footer()+'</body></html>'
    (ROOT/'index.html').write_text(out)


def project_explorer():
    import json
    from proforma import data, mid_panel, high_panel
    d=data();d['projects']=[p for p in d['projects'] if p['slug']=='pixel']
    feed=json.dumps(d,ensure_ascii=False)
    tabs=f'''<div class="pf-tabs js-only" role="tablist" aria-label="Vista de Residencia 01"><button id="tab-medio" data-tab="medio" role="tab" aria-selected="true" aria-controls="demo-medio">{t('Elegir en el plano','Choose on the plan')}</button><button id="tab-alto" data-tab="alto" role="tab" aria-selected="false" aria-controls="demo-alto">{t('Explorar el edificio','Explore the building')}</button></div>'''
    return f'''<section id="experience" class="project-experience"><div class="project-section-heading"><span class="overline">{t('EXPLORA LOS DEPARTAMENTOS','EXPLORE THE APARTMENTS')}</span>{t('Encuentra tu departamento.','Find your apartment.','h2')}<p>{t('Elige un piso y consulta los detalles de un departamento en el plano. También puedes hablar directamente con un asesor.','Choose a floor and view an apartment’s details on the plan. You can also speak directly with an advisor.')}</p></div><div class="project-explorer pf" id="project-explorer" data-project="pixel"><p class="inventory-notice"><b>{t('INVENTARIO ILUSTRATIVO','ILLUSTRATIVE INVENTORY')}</b>{t('Esta muestra usa unidades, superficies, precios y estados de ejemplo. La maqueta es esquemática; no representa una oferta inmobiliaria.','This preview uses sample units, floor areas, prices and statuses. The model is schematic; it is not a property offering.')}</p><div id="demo">{tabs}{mid_panel(d)}{high_panel(d)}</div></div><script type="application/json" id="demo-data">{feed}</script></section>'''


def project():
    from build import map_dialog, tour_dialog
    essential=f'''<div><span class="overline">RESIDENCIA 01 / SECTOR DE EJEMPLO</span>{t('Un espacio<br>para tu <em>día a día.</em>','A space for<br>your <em>everyday.</em>','h1')}<p>{t('Estudios, suites y departamentos en la esquina de Avenida Central y Calle del Parque.','Studios, suites and apartments on the corner of Avenida Central and Calle del Parque.')}</p><div class="action-row">{a('Ver departamentos','View apartments','#homes','button')}{a('Consultar disponibilidad','Enquire about availability','#contact','text-link')}</div></div><figure>{photo('residencia-exterior-render','Fachada y balcones de Residencia 01',eager=True)}<figcaption>RESIDENCIA 01 · SECTOR DE EJEMPLO, QUITO</figcaption></figure>'''
    editorial=f'''<div class="editorial-masthead"><span>RESIDENCIA 01 / SECTOR DE EJEMPLO</span><span>{t('PROYECTO FICTICIO · DEMO','FICTIONAL PROJECT · DEMO')}</span></div><div class="pixel-editorial-title">{t('La vida<br>tiene otro<br><em>color.</em>','Life in<br>a different<br><em>colour.</em>','h1')}<p>{t('El color aparece en la fachada, se transforma en el lobby y acompaña la vida cotidiana. Una mirada a Residencia 01, en Sector de ejemplo.','Colour appears on the façade, transforms in the lobby and accompanies everyday life. A closer look at Residencia 01, in Sector de ejemplo.')}</p><div class="action-row">{a('Ver departamentos','View apartments','#homes','button')}</div></div><figure>{photo('pixel-lobby-render','Techo de colores del lobby Residencia 01 Colors',eager=True)}<figcaption><b>01 / RESIDENCIA 01 COLORS</b><span>{t('Una bienvenida con identidad propia.','A welcome with its own identity.')}</span></figcaption></figure>'''
    immersive=f'''<div class="pixel-immersive-background">{photo('pixel-living-render','Sala, comedor y cocina de un departamento Residencia 01',eager=True)}</div><div class="pixel-immersive-copy"><span class="overline">RESIDENCIA 01 / SECTOR DE EJEMPLO, QUITO</span>{t('Imagina<br>llegar a <em>casa.</em>','Imagine<br>coming <em>home.</em>','h1')}<p>{t('Del edificio a sus interiores. Encuentra un punto de vista, recorre los espacios y descubre dónde empieza tu historia.','From the building to its interiors. Find a perspective, explore the spaces and discover where your story begins.')}</p><div class="action-row">{a('Ver departamentos','View apartments','#homes','button')}{a('Conocer el proyecto','Explore the project','#details','text-link')}</div></div>'''
    facts=f'''<section class="pixel-facts" id="details"><div><span class="overline">{t('RESIDENCIA 01, DE UN VISTAZO','RESIDENCIA 01 AT A GLANCE')}</span>{t('Lo que necesitas<br>para empezar.','What you need<br>to get started.','h2')}<p>{t('Conoce la ubicación y las opciones de vivienda. La ubicación, los espacios y la disponibilidad son ficticios.','Discover the location and home types. Location, spaces and availability are fictional.')}</p></div><dl><div><dt>{t('UBICACIÓN','LOCATION')}</dt><dd>Sector de ejemplo, Quito</dd></div><div><dt>{t('VIVIENDAS','HOMES')}</dt><dd>{t('Estudios, suites y departamentos','Studios, suites and apartments')}</dd></div><div><dt>{t('ESPACIOS COMPARTIDOS','SHARED SPACES')}</dt><dd>Residencia 01 Colors · Residencia 01 Pool</dd></div><div><dt>{t('PRECIOS Y DISPONIBILIDAD','PRICES & AVAILABILITY')}</dt><dd>{a('Consultar con el equipo','Ask the team','#contact','inline-link')}</dd></div><div><dt>{t('ESTADO Y ENTREGA','STATUS & DELIVERY')}</dt><dd>{t('Datos de ejemplo','Sample data')}</dd></div></dl></section>'''
    homes=f'''<section class="pixel-homes" id="homes"><div class="project-section-heading"><span class="overline">{t('TU ESPACIO','YOUR SPACE')}</span>{t('Hay más de una forma<br>de sentirse en casa.','There’s more than one way<br>to feel at home.','h2')}<p>{t('Un ambiente integrado, un dormitorio independiente o espacio para compartir. Elige la distribución que quieres conocer.','An integrated space, a separate bedroom or room to share. Choose the layout you want to explore.')}</p></div><div class="pixel-home-types">'''+''.join(f'''<article><span class="home-type-number">0{i+1}</span>{t(es,en,'h3')}<p>{t(copy,copyen)}</p>{btn('Ver espacios de ejemplo','View sample spaces','text-link js-only','data-open="tour"')}{a('Consultar esta tipología','Enquire about this type','#contact','home-enquiry',f'data-home-type="{key}"')}</article>''' for i,(key,es,en,copy,copyen,slug) in enumerate([('estudio','Estudio','Studio','Un ambiente integrado para organizar tu día a tu manera.','One integrated space to arrange your day your way.','studioNuevo'),('suite','Suite','Suite','Dormitorio independiente y área social: dos ritmos en un mismo hogar.','A separate bedroom and living area: two rhythms in one home.','suiteNuevo'),('departamento','Departamento','Apartment','Sala, comedor y cocina, con opciones de tres o cuatro ambientes.','Living, dining and kitchen areas, with three- or four-space options.','deparNuevo')]))+f'''</div><div class="pixel-interior-story"><figure>{photo('pixel-living-render','Interior de referencia de un departamento Residencia 01')}<figcaption>{t('Interior de referencia · Render conceptual · IA','Reference interior · Concept render · AI')}</figcaption></figure><div><span class="overline">{t('DENTRO DE TU HOGAR','INSIDE YOUR HOME')}</span>{t('Espacio para<br>lo cotidiano.','Room for<br>everyday life.','h3')}<p>{t('La sala, el comedor y la cocina comparten un ambiente. El ventanal enmarca la vista y conecta visualmente los espacios.','The living room, dining area and kitchen share an open space. The window frames the view and visually connects the rooms.')}</p>{btn('Ver secuencia de espacios','View the sequence of spaces','text-link js-only','data-open="tour"')}</div></div></section>'''
    amenities=f'''<section class="pixel-amenities" id="amenities"><div class="project-section-heading"><span class="overline">{t('LA VIDA COMPARTIDA','SHARED SPACES')}</span>{t('Más allá<br>de tu puerta.','Beyond<br>your front door.','h2')}<p>{t('Un lugar para llegar. Otro para hacer una pausa. Conoce los espacios compartidos de Residencia 01.','A place to arrive. Another to pause. Discover Residencia 01’s shared spaces.')}</p></div><div class="pixel-amenity-grid"><figure>{photo('pixel-lobby-render','Lobby Residencia 01 Colors con techo de colores')}<figcaption><h3>Residencia 01 Colors</h3><p>{t('El lobby y su composición de colores.','The lobby and its composition of colours.')}</p></figcaption></figure><figure>{photo('pixel-pool-water-render','Piscina cubierta Residencia 01 Pool')}<figcaption><h3>Residencia 01 Pool</h3><p>{t('Piscina cubierta con zona de descanso.','Indoor swimming pool with a lounge area.')}</p></figcaption></figure></div></section>'''
    from sector import location_section
    location=location_section()
    contact=f'''<section class="pixel-contact" id="contact"><div><span class="overline">{t('ASÍ LLEGA LA CONSULTA','HOW THE ENQUIRY ARRIVES')}</span>{t('De explorar<br>a <em>conversar.</em>','From exploring<br>to <em>conversation.</em>','h2')}<p>{t('La selección del comprador acompaña su consulta. En tu proyecto, este paso puede conectar con WhatsApp o con tu CRM. Aquí puedes escribirnos sobre la experiencia.','The buyer’s selection accompanies their enquiry. In your project, this step can connect to WhatsApp or your CRM. Here you can contact us about the experience.')}</p><p id="home-interest" hidden role="status"></p></div><div class="pixel-contact-links"><a data-enquiry-email href="mailto:alvaroipazr@gmail.com?subject=Demo%20web%20inmobiliaria">{t('Quiero esto para mi proyecto','I want this for my project')}</a>{a('Conocer al equipo','Meet the team','/nosotros/','text-link')}<small>{t('Abre un correo a Andean Software Lab. No se envía nada automáticamente.','Opens an email to Andean Software Lab. Nothing is sent automatically.')}</small></div></section>'''
    out=head('project')+nav(True)+f'<main id="main" class="discover-page">'+direction('essential',essential,'pixel-essential')+direction('editorial',editorial,'pixel-editorial')+direction('immersive',immersive,'pixel-immersive')+facts+homes+project_explorer()+amenities+location+contact+'</main>'+footer()+map_dialog()+tour_dialog()+'</body></html>'

    for route in ('proyecto','pixel'):
        (ROOT/route).mkdir(exist_ok=True);(ROOT/route/'index.html').write_text(out)
